class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        previous_mode = self.view.model.training
        try:
            self.view.model.eval()
            with torch.inference_mode():
                checks = inspect_scoring_contract_and_check_padding(self.view)
                original_metrics = measure_existing_probes(train_loader)
                examples = deterministic_training_prefix_targets(seed=42, max_users_per_dataset=50)
                records = []
                for example in examples:
                    candidates = fixed_unique_candidates(example, seed=42)
                    if candidates is None:
                        record_unavailable(example, 'insufficient eligible candidates')
                        continue
                    baseline = score_actual_model(example.prefix, candidates, checks.readout)
                    for intervention in predeclared_interventions(example, checks):
                        if not intervention.supported:
                            record_unavailable(example, intervention.reason)
                            continue
                        changed = score_actual_model(intervention.sequence, candidates,
                                                     intervention.readout,
                                                     intervention.position_ids)
                        assert_all_finite(baseline, changed)
                        records.append(paired_rank_hit_and_overlap(baseline, changed,
                                                                  tie_rule='score_desc_item_id_asc'))
                metrics = merge(original_metrics, checks.metrics,
                                bootstrap_category_macro(average_repeats_per_user(records),
                                                         replicates=1000, seed=42))
                return {'metrics': metrics,
                        'metric_definitions': explicit_definitions_with_scope_and_missingness(metrics)}
        finally:
            self.view.model.train(previous_mode)

def diagnosis_interpreter_prompt(raw_diagnosis):
    return render_prompt(raw_diagnosis['metrics'],
                         raw_diagnosis['metric_definitions'],
                         instruction='Use measured evidence only. Separate training fit, intervention dependence, implementation artifacts, and official validation accuracy. Treat missing controls as unavailable. Do not infer causal preferences, ownership satisfaction, compatibility without specifications, or unobserved simulator traits.')
